package algorithms.greedy;
import java.util.*;
import java.util.function.*;
import java.math.*;

public class Huffman {
private static class Node{int weight,order;String character;Node left,right;Node(int weight,int order,String character,Node left,Node right){this.weight=weight;this.order=order;this.character=character;this.left=left;this.right=right;}}public record Encoded(String encoded,Map<String,String> codes){}public static Map<String,String> huffmanCodes(String text){Map<String,Integer> f=new LinkedHashMap<>();text.codePoints().forEach(c->f.merge(new String(Character.toChars(c)),1,Integer::sum));Map<String,String> codes=new LinkedHashMap<>();if(f.isEmpty())return codes;if(f.size()==1){codes.put(f.keySet().iterator().next(),"0");return codes;}int order=0;data_structures.heaps.BinaryHeap.Heap<Node> h=new data_structures.heaps.BinaryHeap.Heap<>((a,b)->a.weight!=b.weight?Integer.compare(a.weight,b.weight):Integer.compare(a.order,b.order));for(var e:f.entrySet())h.push(new Node(e.getValue(),order++,e.getKey(),null,null));while(h.size()>1){Node l=h.pop(),r=h.pop();h.push(new Node(l.weight+r.weight,order++,null,l,r));}assign(h.pop(),"",codes);return codes;}private static void assign(Node n,String code,Map<String,String> codes){if(n.character!=null){codes.put(n.character,code);return;}assign(n.left,code+"0",codes);assign(n.right,code+"1",codes);}public static Encoded huffmanEncode(String s){Map<String,String> codes=huffmanCodes(s);StringBuilder o=new StringBuilder();s.codePoints().forEach(c->o.append(codes.get(new String(Character.toChars(c)))));return new Encoded(o.toString(),codes);}public static String huffmanDecode(String s,Map<String,String> codes){Map<String,String> reverse=new HashMap<>();for(var e:codes.entrySet())reverse.put(e.getValue(),e.getKey());StringBuilder o=new StringBuilder();String b="";for(char bit:s.toCharArray()){b+=bit;String c=reverse.get(b);if(c!=null){o.append(c);b="";}}return o.toString();}
}
